-- Stockiha recovery bootstrap: roles, attributes, memberships, ownership, and grants.
-- GENERATED FILE. Do not hand-edit. Regenerate with:
--   pwsh -File scripts/recovery/generate-bootstrap-roles-and-grants.ps1
-- See scripts/recovery/README.md for when this must be regenerated.
--
-- Purpose: run this ONCE against a freshly pg_restore'd Stockiha database
-- (schemas/tables/functions already exist, restored with --no-owner
-- --no-privileges) to rebuild the four Stockiha roles and reapply every
-- object ownership and GRANT the application depends on. Every statement
-- below is idempotent: safe to run twice with no error and no further effect
-- on the second run.
--
-- This script contains NO real password or password hash. Every CREATE ROLE
-- below uses a fixed placeholder password that MUST be changed immediately
-- after this script runs (see the NOTICE at the end of this file).
--
-- Generated: 2026-08-27T16:33:51Z
-- SECURITY DEFINER function owners on the source cluster: stockiha_owner

-- =============================================================
-- Roles (idempotent CREATE, then fixed attribute enforcement)
-- =============================================================
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'stockiha_admin') THEN
        CREATE ROLE "stockiha_admin" PASSWORD 'CHANGE_ME_BOOTSTRAP_PLACEHOLDER';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'stockiha_backup') THEN
        CREATE ROLE "stockiha_backup" PASSWORD 'CHANGE_ME_BOOTSTRAP_PLACEHOLDER';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'stockiha_migrator') THEN
        CREATE ROLE "stockiha_migrator" PASSWORD 'CHANGE_ME_BOOTSTRAP_PLACEHOLDER';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'stockiha_owner') THEN
        CREATE ROLE "stockiha_owner" PASSWORD 'CHANGE_ME_BOOTSTRAP_PLACEHOLDER';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'stockiha_runtime') THEN
        CREATE ROLE "stockiha_runtime" PASSWORD 'CHANGE_ME_BOOTSTRAP_PLACEHOLDER';
    END IF;
END $$;

ALTER ROLE "stockiha_admin" LOGIN INHERIT SUPERUSER CREATEDB CREATEROLE REPLICATION BYPASSRLS;
ALTER ROLE "stockiha_backup" LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
ALTER ROLE "stockiha_migrator" LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
ALTER ROLE "stockiha_owner" NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
ALTER ROLE "stockiha_runtime" LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;

-- ---- Role memberships -----------------------------------------
GRANT "stockiha_owner" TO "stockiha_migrator" WITH ADMIN FALSE, INHERIT FALSE, SET TRUE;

